    ]);

    $role      = $request->attributes->get('auth_role');
    $campusIds = $request->attributes->get('auth_campus_ids', []);

    $signin = StudentSignIn::whereNull('VoidedAt')->find($id);
    if (! $signin) {
        return response()->json(['message' => '記錄不存在或已刪除'], 404);
    }

    if ($role !== 'super_admin' && ! empty($campusIds)) {
        $campusId = (int) ($signin->CampusID ?? 0);
        if (! $campusId || ! in_array($campusId, $campusIds, true)) {
            return response()->json(['message' => 'Forbidden'], 403);
        }
    }

    $input = $request->input('status');

    // self_study 以 Memo 欄位表示，Status 仍維持 'present'
    if ($input === 'self_study') {
        $signin->Memo   = 'self_study';
        $signin->Status = 'present';
        $signin->save();

        return response()->json([
            'ok'           => true,
            'id'           => $signin->id,
            'status'       => 'self_study',
            'status_label' => '自修',
        ]);
    }

    $newStatus = ($input === 'excused') ? 'leave' : $input;

    // 從自修改回一般狀態時清空 Memo
    if ($signin->Memo === 'self_study') {
        $signin->Memo = null;
    }

    $signin->Status = $newStatus;
    $signin->save();

    $statusLabelMap = [
        'present' => '到班',
        'late'    => '遲到',
        'absent'  => '缺席',
        'leave'   => '請假',
    ];

